proc wl_subsurface_destroy*(self: WlSubsurface) {.inline.} =
  ## remove sub-surface interface
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 0'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 1'u32)

proc wl_subsurface_set_position*(self: WlSubsurface, x: int32, y: int32) {.inline.} =
  ## reposition the sub-surface
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 1'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 0'u32, x, y)

proc wl_subsurface_place_above*(self: WlSubsurface, sibling: WlSurface) {.inline.} =
  ## restack the sub-surface
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 2'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 0'u32, cast[pointer](sibling))

proc wl_subsurface_place_below*(self: WlSubsurface, sibling: WlSurface) {.inline.} =
  ## restack the sub-surface
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 3'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 0'u32, cast[pointer](sibling))

proc wl_subsurface_set_sync*(self: WlSubsurface) {.inline.} =
  ## set sub-surface to synchronized mode
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 4'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 0'u32)

proc wl_subsurface_set_desync*(self: WlSubsurface) {.inline.} =
  ## set sub-surface to desynchronized mode
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 5'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 0'u32)

# --- wl_fixes ---

const WL_FIXES_ERROR_INVALID_ACK_REMOVE* = 0'u32

proc wl_fixes_get_user_data*(self: WlFixes): pointer {.inline.} =
  wl_proxy_get_user_data(cast[ptr WlProxy](self))
proc wl_fixes_set_user_data*(self: WlFixes, data: pointer) {.inline.} =
  wl_proxy_set_user_data(cast[ptr WlProxy](self), data)
proc wl_fixes_get_version*(self: WlFixes): uint32 {.inline.} =
  wl_proxy_get_version(cast[ptr WlProxy](self))

proc wl_fixes_destroy*(self: WlFixes) {.inline.} =
  ## destroys this object
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 0'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 1'u32)

proc wl_fixes_destroy_registry*(self: WlFixes, registry: WlRegistry) {.inline.} =
  ## destroy a wl_registry
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 1'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 0'u32, cast[pointer](registry))

proc wl_fixes_ack_global_remove*(self: WlFixes, registry: WlRegistry, name: uint32) {.inline.} =
  ## acknowledge global removal (since version 2)
  discard wl_proxy_marshal_flags(cast[ptr WlProxy](self), 2'u32, nil, wl_proxy_get_version(cast[ptr WlProxy](self)), 0'u32, cast[pointer](registry), name)
